const fs=require('node:fs'),path=require('node:path'),vm=require('node:vm'),assert=require('node:assert/strict');
const root=path.join(__dirname,process.argv.includes('--tree')?'skill-tree-20261006':process.argv.includes('--scale')?'creature-scale-20261006':'adventure-soul-20261006'),api=require(path.join(root,'adventure-director.js')),story=require(path.join(root,'adventure-story.js')),score=require(path.join(root,'adventure-score.js')),html=fs.readFileSync(path.join(root,'index.html'),'utf8');
const results=[],check=(n,f)=>{f();results.push(n)};
for(const m of html.matchAll(/<script(?:\s[^>]*)?>([\s\S]*?)<\/script>/g))new vm.Script(m[1]);for(const f of fs.readdirSync(root).filter(f=>f.endsWith('.js')))new vm.Script(fs.readFileSync(path.join(root,f),'utf8'),{filename:f});
check('all main and side campaign nodes have authored before/mid/after beats',()=>{for(let c=1;c<=8;c++)for(const k of(c===8?[0,1,2,3,4,5,'王']:[1,2,3,'王'])){const b=story.beats[c+'-'+k];assert.ok(b,c+'-'+k);assert.ok(b.before.length&&b.mid.length&&b.after.length)}});
check('required objectives use different world actions',()=>{const required=Object.values(story.beats).filter(b=>b.task?.required);assert.ok(required.length>=6);assert.ok(new Set(required.map(b=>b.task.verb)).size>=4)});
check('optional encounters keep star and beast identity',()=>{assert.match(story.get({inst:'star',def:{nm:'天秤'}}).title,/天秤/);assert.match(story.get({inst:'beast',def:{nm:'金古'}}).title,/金古/)});
check('legacy/malformed adventure state is safe and separate',()=>{assert.deepEqual(api.normalize(null),{version:1,wounds:{},log:{},rests:0});assert.deepEqual(api.normalize({wounds:{warrior:9,bogus:1,mage:-5}}).wounds,{warrior:2,mage:0});assert.equal(api.KEY,'babylon-adventure-v1')});
check('three allied action countdown, not wall-clock or enemy turns',()=>{const d={team:'hero',alive:false};api.down(d,4);assert.equal(d.aidLeft,3);api.tickDown([d],4);assert.equal(d.aidLeft,3);api.tickDown([d],5);api.tickDown([d],6);assert.equal(d.aidLeft,1);assert.equal(api.tickDown([d],7).length,1);assert.equal(d.withdrawn,true);assert.equal(api.tickDown([d],8).length,0)});
check('aid requires alive actor, an unspent action and adjacent safe target',()=>{const u={alive:true,acted:false},d={alive:false,team:'hero',aidLeft:2};assert.equal(api.canAid(u,d,1),true);for(const [a,b,n,blocked]of[[{...u,acted:true},d,1,false],[u,{...d,withdrawn:true},1,false],[u,d,2,false],[u,d,1,true],[u,{...d,aidLeft:0},1,false]])assert.equal(api.canAid(a,b,n,blocked),false)});
check('escape is not defeat and receives no new wound',()=>{const r=api.settle(api.normalize(null),[{cls:'warrior',name:'旅人',alive:false,escaped:true}],true,'8-3',false);assert.equal(r.state.wounds.warrior,0);assert.deepEqual(r.injured,[])});
check('unrescued wound is capped, restored by victory or free camp',()=>{let r=api.settle(api.normalize({wounds:{mage:2}}),[{cls:'mage',name:'米菈',alive:false}],false,'1-1',false);assert.equal(r.state.wounds.mage,2);r=api.settle(r.state,[{cls:'mage',name:'米菈',alive:true}],true,'1-1',true);assert.equal(r.state.wounds.mage,1);assert.equal(r.state.log['1-1'].won,true);assert.equal(r.state.log['1-1'].losses,1);assert.equal(r.state.log['1-1'].task,true)});
check('wounds affect HP and speed only, floor prevents softlock',()=>{assert.deepEqual(api.penalty(100,10,2),{hp:84,spd:8});assert.deepEqual(api.penalty(1,1,2),{hp:1,spd:1})});
check('no permanent death or progress reset added',()=>{const source=fs.readFileSync(path.join(root,'adventure-director.js'),'utf8');assert.ok(!/removeItem|localStorage\.clear|CLEARED\s*=|PROGRESS\s*=/.test(source));assert.match(html,/!o\.withdrawn/);assert.match(source,/if\(!TEST\.on\)/)});
check('music cues separate refuge, danger, loss and liberation',()=>{assert.equal(score.select('title'),'adv_home');assert.equal(score.select('map',{lost:true}),'adv_grief');assert.equal(score.select('boss',{env:'ice'}),'adv_boss_ice');assert.equal(score.select('boss',{escape:true}),'adv_crisis');assert.ok(score.tracks.adv_release&&score.tracks.adv_bond)});
check('score note lengths and instrument names are valid',()=>{const instruments=['flute','harp','bell','strings','brass','bass','timp','snare'];for(const [name,t]of Object.entries(score.tracks)){assert.ok(t.bpm>0&&t.beats>0);for(const p of t.parts){assert.ok(instruments.includes(p.inst));if(p.notes){const length=p.notes.reduce((s,n)=>s+n[1],0);assert.equal(length,t.beats,name+' '+p.inst+' '+length);for(const n of p.notes)assert.ok(n[1]>0&&Number.isFinite(n[1]))}}}});
check('actual audio scheduler uses a short lookahead and stops old cues',()=>{
 const timers=new Map(),notes=[];let next=0;const ac={currentTime:0,state:'running',createGain:()=>({gain:{value:1,setTargetAtTime(){}},connect(){},disconnect(){}})};
 const doc={hidden:false,documentElement:{dataset:{}},addEventListener(){},createElement:()=>({}),querySelector:()=>({appendChild(){}})};
 const c={window:{},document:doc,TRACKS:{},COMPILED:{},BGM:null,AC:ac,STAGE:{env:'ice'},G:{phase:'battle'},units:[],audioCtx:()=>ac,musicBus:()=>({out:{},send:{}}),channels:()=>({}),INST:Object.fromEntries(['flute','harp','bell','strings','brass','bass','timp','snare'].map(n=>[n,(a,d,f,t,dur,v)=>notes.push({inst:n,f,t,dur})])),setInterval:fn=>{timers.set(++next,fn);return next},clearInterval:id=>timers.delete(id),setTimeout(){},show(){},sfx(){},setMusic(){},soundOn:true,console,
 compile:t=>{const spb=60/t.bpm,ev=[];for(const p of t.parts){let b=0;if(p.chords){p.chords.forEach((ch,i)=>ch.split(' ').forEach(n=>ev.push({inst:p.inst,f:440,b:i*p.each,d:p.each,v:p.vol})));continue;}for(const [n,d,v]of p.notes){if(n)ev.push({inst:p.inst,f:440,b,d,v});b+=d;}}return{spb,ev,len:t.beats*spb,once:t.once}}};
 vm.createContext(c);vm.runInContext(fs.readFileSync(path.join(root,'adventure-score.js'),'utf8'),c);const runtime=c.window.AdventureScore.runtime;
 runtime.play('adv_home');assert.ok(notes.length>0&&notes.length<20);assert.ok(notes.every(n=>n.t<=.24));assert.equal(timers.size,1);
 runtime.play('adv_crisis');assert.equal(timers.size,1);assert.equal(doc.documentElement.dataset.scoreCue,'adv_crisis');runtime.stop();assert.equal(timers.size,0);
});
console.log(JSON.stringify({passed:results.length,results},null,2));
const qa=`<script>artReady.then(()=>{
 const nav=document.createElement('nav');nav.id='soulQA';nav.style='position:fixed;top:68px;left:0;right:58px;z-index:230;background:#142631;color:#fff;font:11px sans-serif;padding:4px';nav.innerHTML='<select id="sqNode" aria-label="測試冒險章節">'+NODES.filter(n=>!n.inst).map(n=>'<option value="'+n.id+'">'+n.id+' '+n.nm+'</option>').join('')+'</select><button id="sqLoad">載入冒險</button><button id="sqStory">故事開戰</button><button id="sqDown">同伴倒地</button><button id="sqAid">救援測試</button><button id="sqEnd">我方行動一次</button><button id="sqTask">到任務圈</button><button id="sqClear">突破敵人</button><button id="sqCheck">結算檢查</button><button id="sqLose">全隊倒地</button><button id="sqState">狀態</button><button id="sqHide">收起測試</button><output id="sqOutput"></output>';document.body.appendChild(nav);let busy=false;
 const report=extra=>{const s=AdventureDirector.runtime.session;document.querySelector('#sqOutput').textContent=JSON.stringify({phase:G.phase,mode,score:document.documentElement.dataset.scoreCue,task:s?.beat.task?.name,done:s?.done,points:s?.points.map(p=>({x:p.x,z:p.z,done:p.done})),party:G.party.filter(a=>a.cls).map(a=>({name:a.name,alive:a.alive,hp:a.hp,mhp:a.mhp,aid:a.aidLeft,withdrawn:a.withdrawn,wound:a.wound,acted:a.acted})),state:AdventureDirector.runtime.state,...extra});};
 const run=async f=>{if(busy)return;busy=true;try{await f();report({complete:true})}catch(e){report({error:e.stack});console.error(e)}finally{busy=false}};
 document.querySelector('#sqLoad').onclick=()=>run(async()=>{setup.picks=[{cls:'warrior',name:'亞瑟',col:5,el:'地',lead:true},{cls:'mage',name:'米菈',sex:'f',el:'水'},{cls:'support',name:'艾莉',sex:'f',el:'光'}];for(const c of ['warrior','mage','support'])ROSTER[c]={lv:9,exp:0,adv:true,learned:['ultima']};curNode=NODES.find(n=>n.id===document.querySelector('#sqNode').value);goNode(curNode);buildBattle();chooseZone(ZONES[0]);$('#deploy').hidden=true;$('#bottom').hidden=true;G.phase='battle';mode='act';cur=G.party[0];AdventureDirector.runtime.makePoints();refreshTurn();});
 document.querySelector('#sqStory').onclick=()=>run(()=>startBattle());
 document.querySelector('#sqDown').onclick=()=>run(async()=>{const u=G.party[1];const a=G.party[0],p=DIRS.map(([dx,dz])=>T(a.x+dx,a.z+dz)).find(t=>t&&walkable(t)&&!unitAt(t.x,t.z)&&!t.pit&&Math.abs(t.h-T(a.x,a.z).h)<=a.jump);if(!p)throw Error('No adjacent test tile');u.x=p.x;u.z=p.z;u.pos.copy(tileCenter(u.x,u.z));u.hp=0;await ko(u);cur=a;a.acted=false;mode='act';refreshTurn();});
 document.querySelector('#sqAid').onclick=()=>run(async()=>{const d=G.party[1];cur=G.party[0];cur.acted=false;await perform(cur,SK.adv_aid,d.x,d.z);mode='act';refreshTurn();});
 document.querySelector('#sqEnd').onclick=()=>run(async()=>{const s=AdventureDirector.runtime.session;s.stamp++;for(const u of AdventureDirector.tickDown(units,s.stamp))u.grp.visible=false;AdventureDirector.runtime.status();});
 document.querySelector('#sqTask').onclick=()=>run(async()=>{const p=AdventureDirector.runtime.session.points.find(p=>!p.done),u=G.party[0];if(!p)return;u.x=p.x;u.z=p.z;u.pos.copy(tileCenter(p.x,p.z));u.acted=false;cur=u;mode='act';refreshTurn();});
 document.querySelector('#sqClear').onclick=()=>run(async()=>{for(const u of units.filter(a=>a.alive&&a.team==='enemy')){u.hp=0;await ko(u)}});
 document.querySelector('#sqCheck').onclick=()=>run(()=>checkEnd());document.querySelector('#sqLose').onclick=()=>run(async()=>{for(const u of G.party.filter(a=>a.alive&&a.cls)){u.hp=0;await ko(u)}await checkEnd()});document.querySelector('#sqState').onclick=()=>report();document.querySelector('#sqHide').onclick=()=>nav.style.display='none';
});</script>`;
if(process.argv.includes('--serve'))require('node:http').createServer((req,res)=>{const url=new URL(req.url,'http://localhost'),file=path.resolve(root,'.'+decodeURIComponent(url.pathname==='/'?'/index.html':url.pathname));if(!file.startsWith(root+path.sep)||!fs.existsSync(file)){res.writeHead(404).end();return;}const mime={'.html':'text/html; charset=utf-8','.js':'text/javascript; charset=utf-8','.css':'text/css; charset=utf-8','.jpg':'image/jpeg','.png':'image/png','.webp':'image/webp'};res.writeHead(200,{'Content-Type':mime[path.extname(file)]||'application/octet-stream','Cache-Control':'no-store'});if(file.endsWith('index.html')&&url.searchParams.has('soulqa'))res.end(fs.readFileSync(file,'utf8').replace('</body>',qa+'</body>'));else fs.createReadStream(file).pipe(res)}).listen(4184,'127.0.0.1',()=>console.log('Adventure QA ready:4184'));
